1	# ezpds-ios-template — shared custom XcodeGen project template for BOTH iOS apps
2	# (identity-wallet, admin-companion), wired via `bundle > iOS > template` in each
3	# app's tauri.conf.json. `cargo tauri ios init` renders this Handlebars template
4	# into gen/apple/project.yml on EVERY init (unconditionally, unlike the other
5	# generated files, which are only created when missing), then runs
6	# `xcodegen generate` to rebuild project.pbxproj from it. That makes this file —
7	# not the gitignored generated project — the durable home of the Xcode-project
8	# workarounds that ios-postinit.sh used to re-apply by regex-patching the pbxproj
9	# (see docs/ios-upstream-bugs.md for each workaround's upstream bug).
10	#
11	# upstream-version: tauri-cli 2.11.4
12	# Forked from crates/tauri-cli/templates/mobile/ios/project.yml at that tag; the
13	# pristine copy is committed next to this file as upstream-project.yml so the fork
14	# can be diffed against it. When bumping the tauri-cli pin (the `cargo binstall
15	# tauri-cli --version` lines in .github/workflows/*.yml), refresh
16	# upstream-project.yml from the new tag, re-merge upstream's changes into this
17	# fork, and bump the upstream-version line above — scripts/ios-template-check.sh
18	# (part of `just ci` / `ci-pds`) fails until the versions are back in lockstep.
19	#
20	# ezpds changes vs upstream (each marked with an `ezpds:` comment inline):
21	#   1. Externals gets `buildPhase: none` — keeps libapp.a out of Copy Bundle
22	#      Resources (App Store rejects a raw staticlib in the .app; tauri#13578).
23	#   2. Target settings force ENABLE_USER_SCRIPT_SANDBOXING off (macOS 26 blocks
24	#      Cargo's readdir under the Run Script sandbox), allow the spurious
25	#      "entitlements modified during build" (per-build pbxproj restamp race), and
26	#      link the Apple frameworks the Rust staticlib needs via OTHER_LDFLAGS
27	#      (rendered from `bundle > iOS > frameworks` in tauri.conf.json — rustc's
28	#      #[link(kind="framework")] directives are invisible to Xcode when the crate
29	#      is linked as a staticlib).
30	#   3. The "Build Rust Code" phase re-creates the dev environment before invoking
31	#      the Tauri CLI — Xcode runs it in a clean shell that inherits neither the
32	#      devenv PATH nor the Apple-toolchain overrides from ios-env.sh.
33	#   4. The layered Icon Composer document (apps/<app>/AppIcon.icon — the iOS 26
34	#      Liquid Glass icon) is referenced IN PLACE as a resource, with a fileTypes
35	#      mapping so XcodeGen treats the .icon package as one file. Xcode 26 prefers
36	#      it over the same-named appiconset, which stays as the older-toolchain
37	#      fallback (regenerated by postinit's Patch G).
38	#   NOTE on entitlements: this file keeps tauri-cli's DEFAULT entitlements path
39	#      ({{app.name}}_iOS/{{app.name}}_iOS.entitlements). tauri-cli's own build-time
40	#      codesign reads that default path regardless of what this template says, so
41	#      repointing it here leaves that path fileless and breaks signing ("cannot
42	#      read entitlement data"). The wallet's iCloud entitlements are instead
43	#      injected INTO the generated default file after init by ios-postinit.sh's
44	#      Patch H (from the tracked apps/<app>/src-tauri/Entitlements.ios.plist),
45	#      the same tracked-source→gitignored-tree pattern as the Patch G app icon.
46	name: {{app.name}}
47	options:
48	  bundleIdPrefix: {{app.identifier}}
49	  deploymentTarget:
50	    iOS: {{apple.ios-version}}
51	  # ezpds: treat Icon Composer .icon packages as single-file resources — XcodeGen
52	  # otherwise explodes the package into loose icon.json/svg resources, which Xcode
53	  # does not recognize as an app icon (XcodeGen#1556).
54	  fileTypes:
55	    icon:
56	      file: true
57	fileGroups: [{{join file-groups}}]
58	configs:
59	  debug: debug
60	  release: release
61	settingGroups:
62	  app:
63	    base:
64	      PRODUCT_NAME: {{app.stylized-name}}
65	      PRODUCT_BUNDLE_IDENTIFIER: {{app.identifier}}
66	      {{#if apple.development-team}}
67	      DEVELOPMENT_TEAM: {{apple.development-team}}
68	      {{/if}}
69	targetTemplates:
70	  app:
71	    type: application
72	    sources:
73	      - path: Sources
74	    scheme:
75	      environmentVariables:
76	        RUST_BACKTRACE: full
77	        RUST_LOG: info
78	    settings:
79	      groups: [app]
80	targets:
81	  {{app.name}}_iOS:
82	    type: application
83	    platform: iOS
84	    sources:
85	      - path: Sources
86	      - path: Assets.xcassets
87	      # ezpds: the layered Icon Composer document (iOS 26 Liquid Glass), checked in
88	      # at apps/<app>/AppIcon.icon and referenced in place — ../../.. resolves from
89	      # gen/apple to the app dir, so nothing needs copying into the generated tree.
90	      # Compiled/validated by actool in `just <recipe>-pr-check` (`just _icon-compile`).
91	      - path: ../../../AppIcon.icon
92	        buildPhase: resources
93	      # ezpds: no buildPhase for Externals — XcodeGen otherwise infers `resources`
94	      # and copies the raw libapp.a into the .app, which App Store upload rejects
95	      # ("Invalid bundle structure", tauri#13578). The staticlib is still LINKED
96	      # via the `framework: libapp.a` dependency + LIBRARY_SEARCH_PATHS below.
97	      - path: Externals
98	        buildPhase: none
99	      - path: {{app.name}}_iOS
100	      - path: {{app.asset-dir}}
101	        buildPhase: resources
102	        type: folder
103	      {{~#each asset-catalogs}}
104	      - {{prefix-path this}}{{/each}}
105	      {{~#each ios-additional-targets}}
106	      - path: {{prefix-path this}}{{/each}}
107	      - path: LaunchScreen.storyboard
108	    info:
109	      path: {{app.name}}_iOS/Info.plist
110	      properties:
111	        LSRequiresIPhoneOS: true
112	        UILaunchStoryboardName: LaunchScreen
113	        UIRequiredDeviceCapabilities: [arm64, metal]
114	        UISupportedInterfaceOrientations:
115	          - UIInterfaceOrientationPortrait
116	          - UIInterfaceOrientationLandscapeLeft
117	          - UIInterfaceOrientationLandscapeRight
118	        UISupportedInterfaceOrientations~ipad:
119	          - UIInterfaceOrientationPortrait
120	          - UIInterfaceOrientationPortraitUpsideDown
121	          - UIInterfaceOrientationLandscapeLeft
122	          - UIInterfaceOrientationLandscapeRight
123	        CFBundleShortVersionString: {{apple.bundle-version-short}}
124	        CFBundleVersion: "{{apple.bundle-version}}"
125	        {{~#each apple.plist-pairs}}
126	        {{this.key}}: {{this.value}}{{/each}}
127	    entitlements:
128	      # tauri-cli's default path. Its CONTENT is overwritten after init by
129	      # ios-postinit.sh's Patch H (from the tracked src-tauri/Entitlements.ios.plist)
130	      # — see the header note. Do NOT repoint this: tauri's build-time codesign
131	      # reads this exact path and fails if it is fileless.
132	      path: {{app.name}}_iOS/{{app.name}}_iOS.entitlements
133	    scheme:
134	      environmentVariables:
135	        RUST_BACKTRACE: full
136	        RUST_LOG: info
137	      {{~#if ios-command-line-arguments}}
138	      commandLineArguments:
139	      {{~#each ios-command-line-arguments}}
140	        "{{this}}": true
141	      {{/each}}{{~/if}}
142	    settings:
143	      base:
144	        ENABLE_BITCODE: false
145	        ARCHS: [{{join ios-valid-archs}}]
146	        VALID_ARCHS: {{~#each ios-valid-archs}} {{this}} {{/each}}
147	        LIBRARY_SEARCH_PATHS[arch=x86_64]: $(inherited) $(PROJECT_DIR)/Externals/x86_64/$(CONFIGURATION) $(SDKROOT)/usr/lib/swift $(DEVELOPER_DIR)/Toolchains/XcodeDefault.xctoolchain/usr/lib/swift/$(PLATFORM_NAME) $(DEVELOPER_DIR)/Toolchains/XcodeDefault.xctoolchain/usr/lib/swift-5.0/$(PLATFORM_NAME)
148	        LIBRARY_SEARCH_PATHS[arch=arm64]: $(inherited) $(PROJECT_DIR)/Externals/arm64/$(CONFIGURATION) $(SDKROOT)/usr/lib/swift $(DEVELOPER_DIR)/Toolchains/XcodeDefault.xctoolchain/usr/lib/swift/$(PLATFORM_NAME) $(DEVELOPER_DIR)/Toolchains/XcodeDefault.xctoolchain/usr/lib/swift-5.0/$(PLATFORM_NAME)
149	        ALWAYS_EMBED_SWIFT_STANDARD_LIBRARIES: true
150	        EXCLUDED_ARCHS[sdk=iphoneos*]: x86_64
151	        # ezpds: macOS 26's Run Script sandbox blocks Cargo's readdir during
152	        # package fingerprinting (docs/ios-upstream-bugs.md Bug 2). Quoted so
153	        # every YAML parser reads the same string (bare NO is a YAML 1.1 bool).
154	        ENABLE_USER_SCRIPT_SANDBOXING: "NO"
155	        # ezpds: `cargo tauri ios build` restamps the pbxproj on every run, which
156	        # makes Xcode's incremental packaging intermittently flag the
157	        # (never-actually-modified) entitlements file as "modified during the
158	        # build" (docs/ios-upstream-bugs.md Bug 3).
159	        CODE_SIGN_ALLOW_ENTITLEMENTS_MODIFICATION: "YES"
160	        # ezpds: link the Apple frameworks the Rust staticlib's dependencies
161	        # reference (from `bundle > iOS > frameworks` in tauri.conf.json). The
162	        # same list also renders `- sdk:` dependencies below (upstream behavior);
163	        # the explicit OTHER_LDFLAGS is belt-and-braces for staticlib symbol
164	        # resolution — duplicate -framework flags are harmless to the linker.
165	        OTHER_LDFLAGS: $(inherited){{#each ios-frameworks}} -framework {{this}}{{/each}}
166	      groups: [app]
167	    dependencies:
168	      - framework: {{ lib-output-file-name }}
169	        embed: false
170	      {{~#each ios-libraries}}
171	      - framework: {{this}}
172	        embed: false{{/each}}{{#if ios-vendor-frameworks}}{{~#each ios-vendor-frameworks}}
173	      - framework: {{this}}{{/each}}{{/if}}{{#if ios-vendor-sdks}}{{~#each ios-vendor-sdks}}
174	      - sdk: {{prefix-path this}}{{/each}}{{/if}}
175	      - sdk: CoreGraphics.framework
176	      - sdk: Metal.framework
177	      - sdk: MetalKit.framework
178	      - sdk: QuartzCore.framework
179	      - sdk: Security.framework
180	      - sdk: UIKit.framework{{#if this.ios-frameworks}}{{~#each ios-frameworks}}
181	      - sdk: {{this}}.framework{{/each}}{{/if}}
182	      - sdk: WebKit.framework
183	    preBuildScripts:
184	      {{~#each ios-pre-build-scripts}}{{#if this.path}}
185	      - path {{this.path}}{{/if}}{{#if this.script}}
186	      - script: {{this.script}}{{/if}}{{#if this.name}}
187	        name: {{this.name}}{{/if}}{{#if this.input-files}}
188	        inputFiles: {{~#each this.input-files}}
189	          - {{this}}{{/each}}{{/if}}{{#if this.output-files}}
190	        outputFiles: {{~#each this.output-files}}
191	          - {{this}}{{/each}}{{/if}}{{#if this.input-file-lists}}
192	        inputFileLists: {{~#each this.output-files}}
193	          - {{this}}{{/each}}{{/if}}{{#if this.output-file-lists}}
194	        outputFileLists: {{~#each this.output-files}}
195	          - {{this}}{{/each}}{{/if}}{{#if this.shell}}
196	        shell: {{this.shell}}{{/if}}{{#if this.show-env-vars}}
197	        showEnvVars: {{this.show_env_vars}}{{/if}}{{#if this.run-only-when-installing}}
198	        runOnlyWhenInstalling: {{this.run-only-when-installing}}{{/if}}{{#if this.based-on-dependency-analysis}}
199	        basedOnDependencyAnalysis: {{this.based-on-dependency-analysis}}{{/if}}{{#if this.discovered-dependency-file}}
200	        discoveredDependencyFile: {{this.discovered-dependency-file}}{{/if}}
201	      {{~/each}}
202	
203	      # ezpds: Xcode runs this phase in a clean shell that inherits neither the
204	      # devenv PATH (cargo, cargo-tauri, node, pnpm) nor the Apple-toolchain
205	      # overrides — re-create both before invoking the Tauri CLI. Paths are
206	      # derived from $SRCROOT (= apps/<app>/src-tauri/gen/apple), never baked in,
207	      # so the same committed template works on every machine and on CI.
208	      - script: |
209	          # >>> ezpds-ios-env >>>
210	          export EZPDS_IOS_BUILD=1
211	          if [ -d "$SRCROOT/../../../../../.devenv/profile/bin" ]; then
212	            PATH="$SRCROOT/../../../../../.devenv/profile/bin:$PATH"
213	          fi
214	          PATH="${CARGO_HOME:-$HOME/.cargo}/bin:$PATH"
215	          export PATH
216	          if [ -f "$SRCROOT/../../../scripts/ios-env.sh" ]; then
217	            . "$SRCROOT/../../../scripts/ios-env.sh"
218	          fi
219	          # <<< ezpds-ios-env <<<
220	          {{ tauri-binary }} {{ tauri-binary-args-str }} -v --platform ${PLATFORM_DISPLAY_NAME:?} --sdk-root ${SDKROOT:?} --framework-search-paths "${FRAMEWORK_SEARCH_PATHS:?}" --header-search-paths "${HEADER_SEARCH_PATHS:?}" --gcc-preprocessor-definitions "${GCC_PREPROCESSOR_DEFINITIONS:-}" --configuration ${CONFIGURATION:?} ${FORCE_COLOR} ${ARCHS:?}
221	        name: Build Rust Code
222	        basedOnDependencyAnalysis: false
223	        outputFiles:
224	          - $(SRCROOT)/Externals/x86_64/${CONFIGURATION}/{{ lib-output-file-name }}
225	          - $(SRCROOT)/Externals/arm64/${CONFIGURATION}/{{ lib-output-file-name }}
226	    {{~#if ios-post-compile-scripts}}
227	    postCompileScripts:
228	      {{~#each ios-post-compile-scripts}}{{#if this.path}}
229	      - path {{this.path}}{{/if}}{{#if this.script}}
230	      - script: {{this.script}}{{/if}}{{#if this.name}}
231	        name: {{this.name}}{{/if}}{{#if this.input-files}}
232	        inputFiles: {{~#each this.input-files}}
233	          - {{this}}{{/each}}{{/if}}{{#if this.output-files}}
234	        outputFiles: {{~#each this.output-files}}
235	          - {{this}}{{/each}}{{/if}}{{#if this.input-file-lists}}
236	        inputFileLists: {{~#each this.output-files}}
237	          - {{this}}{{/each}}{{/if}}{{#if this.output-file-lists}}
238	        outputFileLists: {{~#each this.output-files}}
239	          - {{this}}{{/each}}{{/if}}{{#if this.shell}}
240	        shell: {{this.shell}}{{/if}}{{#if this.show-env-vars}}
241	        showEnvVars: {{this.show_env_vars}}{{/if}}{{#if this.run-only-when-installing}}
242	        runOnlyWhenInstalling: {{this.run-only-when-installing}}{{/if}}{{#if this.based-on-dependency-analysis}}
243	        basedOnDependencyAnalysis: {{this.based-on-dependency-analysis}}{{/if}}{{#if this.discovered-dependency-file}}
244	        discoveredDependencyFile: {{this.discovered-dependency-file}}{{/if}}
245	      {{~/each~}}
246	    {{~/if~}}
